  1	// Pure data-world helpers shared by the provider, the shell and tests. No React here.
  2	import type { BundleIndexEntry, RunBundle } from "../../../core/src/schema";
  3	import type { Certificate } from "../../../core/src/schema";
  4	import type { CatalogOrigin as DataSource } from "../data";
  5	
  6	/**
  7	 * Live     = the data layer is in live mode (a local `notary serve` answered /api/health) and the selected run is real.
  8	 * Recorded = real published bundles from static files.
  9	 * Fixture  = the selected run is fixture data (bundle.sample), wherever it came from.
 10	 */
 11	export type DataMode = "live" | "recorded" | "fixture";
 12	
 13	export function resolveDataMode(
 14	  source: DataSource,
 15	  selected?: Pick<BundleIndexEntry, "sample">,
 16	): DataMode {
 17	  if (selected?.sample) return "fixture";
 18	  return source === "api" ? "live" : "recorded";
 19	}
 20	
 21	/**
 22	 * `?fixtures=1`: the development-only view of the fixture runs (bundles/fixture, sample: true).
 23	 * Without it the dashboard and the landing show real runs only, and an empty state when none is
 24	 * published; with it they show fixture runs only, under the fixture disclosure. Never both at once.
 25	 */
 26	export const FIXTURES_PARAM = "fixtures";
 27	
 28	/** True when a query string (or URLSearchParams) asks for the fixture view. */
 29	export function fixturesRequested(search: string | URLSearchParams | null | undefined): boolean {
 30	  if (!search) return false;
 31	  const params = typeof search === "string" ? new URLSearchParams(search) : search;
 32	  return params.get(FIXTURES_PARAM) === "1";
 33	}
 34	
 35	/** The fixture flag of the page the browser is on (false outside a browser). */
 36	export const fixturesInLocation = (): boolean => fixturesRequested(globalThis.location?.search);
 37	
 38	/**
 39	 * The runs a view may show. Default: real runs only (live ones still running included). With the
 40	 * fixture flag: finished fixture runs only. A fixture run is never shown without the flag, and a
 41	 * real run is never mixed into the fixture view.
 42	 */
 43	export function visibleRuns<T extends { sample?: boolean; state?: string }>(entries: readonly T[], fixtures: boolean): T[] {
 44	  return entries.filter((e) => {
 45	    const sample = e.state === "running" ? false : !!e.sample;
 46	    return fixtures ? sample && e.state !== "running" : !sample;
 47	  });
 48	}
 49	
 50	/** The empty state's next step when no real run is published. */
 51	export const NO_RUNS_COMMANDS = ["pnpm notary notarize --tool crustdata", "pnpm notary export"] as const;
 52	
 53	export const MODE_LABEL: Record<DataMode, string> = {
 54	  live: "Live",
 55	  recorded: "Recorded",
 56	  fixture: "Fixture",
 57	};
 58	
 59	export type RunGroup = {
 60	  kind: "live" | "recorded" | "fixture";
 61	  label: string;
 62	  runs: BundleIndexEntry[];
 63	};
 64	
 65	/**
 66	 * Run picker sections: real runs first, then recorded fixtures. Fixture and real runs are never in
 67	 * the same section. Empty sections are dropped.
 68	 */
 69	export function groupRuns(
 70	  entries: BundleIndexEntry[],
 71	  source: DataSource,
 72	): RunGroup[] {
 73	  const sorted = [...entries].sort((a, b) =>
 74	    b.startedAt.localeCompare(a.startedAt),
 75	  );
 76	  const real = sorted.filter((e) => !e.sample);
 77	  const fixture = sorted.filter((e) => e.sample);
 78	  const groups: RunGroup[] = [
 79	    source === "api"
 80	      ? { kind: "live", label: "Live runs", runs: real }
 81	      : { kind: "recorded", label: "Recorded runs", runs: real },
 82	    {
 83	      kind: "fixture",
 84	      label: "Fixture runs",
 85	      runs: fixture,
 86	    },
 87	  ];
 88	  return groups.filter((g) => g.runs.length > 0);
 89	}
 90	
 91	/**
 92	 * Default selection: a guarded queue run, preferring real data; else the newest run. Within a
 93	 * cohort, live recordings come before their replays (a replay re-serves cassettes and carries
 94	 * fewer events).
 95	 */
 96	export function defaultRunId(
 97	  entries: Pick<BundleIndexEntry, "runId" | "sample" | "kind" | "variant" | "startedAt" | "mode">[],
 98	): string | undefined {
 99	  const sorted = [...entries].sort((a, b) =>
100	    b.startedAt.localeCompare(a.startedAt),
101	  );
102	  const real = sorted.some((e) => !e.sample)
103	    ? sorted.filter((e) => !e.sample)
104	    : sorted;
105	  const cohort = [...real.filter((e) => e.mode !== "replay"), ...real.filter((e) => e.mode === "replay")];
106	  return (
107	    cohort.find((e) => e.kind === "run" && e.variant === "guarded") ??
108	    cohort[0]
109	  )?.runId;
110	}
111	
112	/** Same-cohort baseline candidates (fixture with fixture, real with real), never the run itself. */
113	export function baselineCandidates(
114	  bundle: RunBundle | undefined,
115	  bundles: RunBundle[],
116	): RunBundle[] {
117	  if (!bundle) return [];
118	  return bundles.filter(
119	    (b) => b.runId !== bundle.runId && b.sample === bundle.sample,
120	  );
121	}
122	
123	export function pickBaseline(
124	  bundle: RunBundle | undefined,
125	  bundles: RunBundle[],
126	  requested: string | null,
127	): RunBundle | undefined {
128	  const candidates = baselineCandidates(bundle, bundles);
129	  return (
130	    candidates.find((b) => b.runId === requested) ??
131	    candidates.find(
132	      (b) =>
133	        b.kind === "run" &&
134	        b.variant === (bundle?.variant === "naive" ? "guarded" : "naive") &&
135	        // Fixture scenarios share a runId prefix; prefer the same scenario.
136	        scenarioKey(b.runId) === scenarioKey(bundle!.runId),
137	    ) ??
138	    candidates.find(
139	      (b) =>
140	        b.kind === "run" &&
141	        b.variant === (bundle?.variant === "naive" ? "guarded" : "naive"),
142	    ) ??
143	    candidates.find((b) => b.kind === bundle?.kind) ??
144	    candidates[0]
145	  );
146	}
147	
148	/** Runs whose ids differ only in their trailing kind/variant share a key ("demo-change-api"). */
149	export function scenarioKey(runId: string): string {
150	  return runId.replace(/-(run|notarize)-[a-z]+$/, "");
151	}
152	
153	export const heldCount = (bundle?: RunBundle) =>
154	  bundle ? bundle.decisions.filter((d) => d.status === "held").length : 0;
155	
156	/**
157	 * `/app/...` path with the selected run (and optional extra params) in the query string. A query
158	 * already in `path` is kept (its `run` wins, so a record path can pin the run it belongs to).
159	 */
160	export function withRun(
161	  path: string,
162	  runId: string | undefined,
163	  extra: Record<string, string | undefined> = {},
164	): string {
165	  const [base, query = ""] = path.split("?", 2) as [string, string?];
166	  const own = new URLSearchParams(query);
167	  const params = new URLSearchParams();
168	  const run = own.get("run") ?? runId;
169	  if (run) params.set("run", run);
170	  for (const [k, v] of own) if (k !== "run") params.set(k, v);
171	  for (const [k, v] of Object.entries(extra)) if (v) params.set(k, v);
172	  // The development-only fixture view stays on while navigating inside the dashboard.
173	  if (fixturesInLocation() && !params.has(FIXTURES_PARAM)) params.set(FIXTURES_PARAM, "1");
174	  const q = params.toString();
175	  return q ? `${base}?${q}` : base;
176	}
177	
178	/**
179	 * Where each record kind is shown. Decisions and probes live in the Run page's transcript
180	 * (`?decision=` / `?probe=` focus the record); beliefs and claims live with their certificates;
181	 * certificates have their own page.
182	 */
183	export const recordPath = {
184	  decision: (id: string) => keepView(`/app/run?decision=${encodeURIComponent(id)}`),
185	  probe: (id: string) => keepView(`/app/run?probe=${encodeURIComponent(id)}`),
186	  belief: (id: string) => keepView(`/app/certificates?belief=${encodeURIComponent(id)}`),
187	  certificate: (id: string) => keepView(`/app/certificates/${encodeURIComponent(id)}`),
188	  run: (id: string) => keepView(`/app/run?run=${encodeURIComponent(id)}`),
189	  report: (tool: string) => keepView(`/app/certificates?tool=${encodeURIComponent(tool)}`),
190	};
191	
192	/** Keep the development-only fixture view (`?fixtures=1`) on a dashboard path when it is on now. */
193	export function keepView(path: string): string {
194	  if (!fixturesInLocation() || /[?&]fixtures=1(&|$)/.test(path)) return path;
195	  return `${path}${path.includes("?") ? "&" : "?"}${FIXTURES_PARAM}=1`;
196	}
197	
198	export type PaletteEntry = {
199	  group: "Decisions" | "Probes" | "Beliefs" | "Certificates";
200	  id: string;
201	  label: string;
202	  hint: string;
203	  path: string;
204	};
205	
206	/** Command-palette records for the selected run, all derived from its bundle (and its certificate world). */
207	export function paletteEntries(
208	  bundle: RunBundle | undefined,
209	  certificates: Certificate[] = [],
210	): PaletteEntry[] {
211	  if (!bundle) return [];
212	  const beliefs = new Map(
213	    [...bundle.beliefs.before, ...bundle.beliefs.after].map((b) => [b.id, b]),
214	  );
215	  return [
216	    ...bundle.decisions.map((d) => ({
217	      group: "Decisions" as const,
218	      id: d.id,
219	      label: `${d.requestId} · ${d.requestType.replaceAll("_", " ")}`,
220	      hint: `${d.status} · ${d.customerId}`,
221	      path: withRun(recordPath.decision(d.id), bundle.runId),
222	    })),
223	    ...bundle.probes.map((p) => ({
224	      group: "Probes" as const,
225	      id: p.id,
226	      label: `${p.id} · ${p.template.replaceAll("_", " ")}`,
227	      hint: `${p.verdict ?? "pending"} · ${p.claimId}`,
228	      path: withRun(recordPath.probe(p.id), bundle.runId),
229	    })),
230	    ...[...beliefs.values()].map((b) => ({
231	      group: "Beliefs" as const,
232	      id: b.id,
233	      label: b.statement,
234	      hint: `${b.status} · ${b.claimId}`,
235	      path: withRun(recordPath.belief(b.id), bundle.runId),
236	    })),
237	    ...certificates.map((c) => ({
238	      group: "Certificates" as const,
239	      id: c.id,
240	      label: `${c.claimId} · ${c.verdict}`,
241	      hint: `${c.status} · ${c.tool}`,
242	      path: withRun(recordPath.certificate(c.id), bundle.runId),
243	    })),
244	  ];
245	}
  1	// One provider for the dashboard's data world, read through the data layer (src/data): the run
  2	// list of the selected DataSource (live `notary serve` or replay of published files), every
  3	// hash-verified bundle, the selected run (from ?run=), its same-cohort baseline
  4	// (?baseline=), the certificate world matching the selected run, and the tool evidence file.
  5	import {
  6	  createContext,
  7	  useCallback,
  8	  useContext,
  9	  useEffect,
 10	  useMemo,
 11	  useState,
 12	  type ReactNode,
 13	} from "react";
 14	import { useSearchParams } from "react-router";
 15	import type { BundleIndexEntry, RunBundle } from "../../../core/src/schema";
 16	import {
 17	  byNewest,
 18	  entryOfBundle,
 19	  finishedEntries,
 20	  loadEvidence,
 21	  toCertificateView,
 22	  useDataSource,
 23	  type CatalogOrigin,
 24	  type CertificateView,
 25	  type DataSource,
 26	  type EvidenceEntry,
 27	  type RunEntry,
 28	} from "../data";
 29	import {
 30	  baselineCandidates,
 31	  defaultRunId,
 32	  fixturesRequested,
 33	  groupRuns,
 34	  pickBaseline,
 35	  resolveDataMode,
 36	  visibleRuns,
 37	  type DataMode,
 38	  type RunGroup,
 39	} from "./links";
 40	
 41	export type { EvidenceEntry };
 42	
 43	export type Loadable<T> =
 44	  | { status: "loading" }
 45	  | { status: "ready"; data: T }
 46	  | { status: "missing" }
 47	  | { status: "error"; error: string };
 48	
 49	export type DataContextValue = {
 50	  mode: DataMode;
 51	  /** "api" = live DataSource (local `notary serve`), "static" = replay of published files. */
 52	  source: CatalogOrigin;
 53	  /** The data layer's source. Pages call it for anything beyond the catalog (timelines, approvals, ask). */
 54	  dataSource: DataSource;
 55	  /** Runs the live server reports as still running (no bundle yet). Empty in replay. */
 56	  running: RunEntry[];
 57	  /**
 58	   * True under `?fixtures=1` (development only): the catalog is the fixture runs and pages carry the
 59	   * fixture disclosure. Otherwise the catalog is real runs only; fixture runs are never listed.
 60	   */
 61	  fixtures: boolean;
 62	  /** The visible index entries (real runs, or fixture runs under `?fixtures=1`). Use `runGroups` to present them. */
 63	  runs: BundleIndexEntry[];
 64	  runGroups: RunGroup[];
 65	  /** Every visible verified bundle: one cohort only (real, or fixture under `?fixtures=1`). */
 66	  bundles: RunBundle[];
 67	  /** The selected run, hash-verified. Undefined while loading, on error or when nothing is published. */
 68	  bundle?: RunBundle;
 69	  selectedRunId?: string;
 70	  /** ?run= named a run that is not in the catalog. */
 71	  missingRunId?: string;
 72	  baseline?: RunBundle;
 73	  baselineCandidates: RunBundle[];
 74	  setRun: (runId: string) => void;
 75	  setBaseline: (runId: string) => void;
 76	  loading: boolean;
 77	  error?: string;
 78	  reload: () => void;
 79	  certificates: Loadable<CertificateView>;
 80	  evidence: Loadable<EvidenceEntry[]>;
 81	};
 82	
 83	const DataContext = createContext<DataContextValue | null>(null);
 84	
 85	export function useData(): DataContextValue {
 86	  const ctx = useContext(DataContext);
 87	  if (!ctx) throw new Error("useData must be used within a DataProvider.");
 88	  return ctx;
 89	}
 90	
 91	/** The data world when inside a DataProvider; undefined in isolated renders (tests). */
 92	export function useOptionalData(): DataContextValue | undefined {
 93	  return useContext(DataContext) ?? undefined;
 94	}
 95	
 96	type CatalogState =
 97	  | { status: "loading" }
 98	  | { status: "error"; error: string }
 99	  | {
100	      status: "ready";
101	      source: CatalogOrigin;
102	      entries: BundleIndexEntry[];
103	      running: RunEntry[];
104	      bundles: RunBundle[];
105	    };
106	
107	export function DataProvider({ children }: { children: ReactNode }) {
108	  const { source: dataSource, mode: sourceMode, ready: sourceReady } = useDataSource();
109	  const [params, setParams] = useSearchParams();
110	  const fixtures = fixturesRequested(params);
111	  const [catalog, setCatalog] = useState<CatalogState>({ status: "loading" });
112	  const [reloadKey, setReloadKey] = useState(0);
113	  const [evidence, setEvidence] = useState<Loadable<EvidenceEntry[]>>({
114	    status: "loading",
115	  });
116	  const [certificates, setCertificates] = useState<
117	    Loadable<CertificateView>
118	  >({ status: "loading" });
119	
120	  useEffect(() => {
121	    if (!sourceReady) return;
122	    const controller = new AbortController();
123	    setCatalog({ status: "loading" });
124	    (async () => {
125	      // Real runs only, or fixture runs only under ?fixtures=1. Hidden runs are not even fetched.
126	      const runs = visibleRuns(await dataSource.listRuns(controller.signal), fixtures);
127	      const entries = finishedEntries(runs).sort(byNewest);
128	      // Every bundle is schema-checked and hash-verified by the data layer before it arrives here.
129	      const bundles = (
130	        await Promise.all(entries.map((e) => dataSource.getRun(e.runId, controller.signal)))
131	      ).sort(byNewest);
132	      return {
133	        source: (sourceMode === "live" ? "api" : "static") as CatalogOrigin,
134	        entries,
135	        running: runs.filter((r) => r.state === "running"),
136	        bundles,
137	      };
138	    })()
139	      .then((world) => {
140	        if (!controller.signal.aborted)
141	          setCatalog({ status: "ready", ...world });
142	      })
143	      .catch((e: Error) => {
144	        if (!controller.signal.aborted)
145	          setCatalog({ status: "error", error: e.message });
146	      });
147	    return () => controller.abort();
148	  }, [reloadKey, dataSource, sourceMode, sourceReady, fixtures]);
149	
150	  useEffect(() => {
151	    const controller = new AbortController();
152	    setEvidence({ status: "loading" });
153	    loadEvidence(controller.signal)
154	      .then((entries) => {
155	        if (!controller.signal.aborted)
156	          setEvidence(
157	            entries.length
158	              ? { status: "ready", data: entries }
159	              : { status: "missing" },
160	          );
161	      })
162	      .catch((e: Error) => {
163	        if (!controller.signal.aborted)
164	          setEvidence({ status: "error", error: e.message });
165	      });
166	    return () => controller.abort();
167	  }, [reloadKey]);
168	
169	  const requested = params.get("run");
170	  const ready = catalog.status === "ready" ? catalog : undefined;
171	  const bundles = useMemo(() => ready?.bundles ?? [], [ready]);
172	  const entries = useMemo(() => ready?.entries ?? [], [ready]);
173	  const fallbackId = useMemo(() => defaultRunId(entries), [entries]);
174	  const bundle = requested
175	    ? bundles.find((b) => b.runId === requested)
176	    : bundles.find((b) => b.runId === fallbackId);
177	  const missingRunId =
178	    ready && requested && !bundle ? requested : undefined;
179	
180	  // Keep the selected run in the URL so every page is shareable as-is.
181	  useEffect(() => {
182	    if (ready && !requested && fallbackId)
183	      setParams(
184	        (p) => {
185	          const next = new URLSearchParams(p);
186	          next.set("run", fallbackId);
187	          return next;
188	        },
189	        { replace: true },
190	      );
191	  }, [ready, requested, fallbackId, setParams]);
192	
193	  const certKey = bundle ? `${bundle.sample}:${bundle.runId}` : "";
194	  useEffect(() => {
195	    if (!bundle) {
196	      setCertificates({ status: "missing" });
197	      return;
198	    }
199	    const controller = new AbortController();
200	    setCertificates({ status: "loading" });
201	    dataSource
202	      .certificates(entryOfBundle(bundle), controller.signal)
203	      .then((world) => {
204	        if (controller.signal.aborted) return;
205	        const view = toCertificateView(world);
206	        setCertificates(view ? { status: "ready", data: view } : { status: "missing" });
207	      })
208	      .catch((e: Error) => {
209	        if (!controller.signal.aborted)
210	          setCertificates({ status: "error", error: e.message });
211	      });
212	    return () => controller.abort();
213	    // eslint-disable-next-line react-hooks/exhaustive-deps
214	  }, [certKey, reloadKey, dataSource]);
215	
216	  const setRun = useCallback(
217	    (runId: string) =>
218	      setParams((p) => {
219	        const next = new URLSearchParams(p);
220	        next.set("run", runId);
221	        next.delete("baseline");
222	        return next;
223	      }),
224	    [setParams],
225	  );
226	  const setBaseline = useCallback(
227	    (runId: string) =>
228	      setParams((p) => {
229	        const next = new URLSearchParams(p);
230	        next.set("baseline", runId);
231	        return next;
232	      }),
233	    [setParams],
234	  );
235	  const reload = useCallback(() => setReloadKey((v) => v + 1), []);
236	
237	  const source: CatalogOrigin = ready?.source ?? (sourceMode === "live" ? "api" : "static");
238	  const value: DataContextValue = {
239	    mode: resolveDataMode(source, bundle),
240	    source,
241	    dataSource,
242	    fixtures,
243	    running: ready?.running ?? [],
244	    runs: entries,
245	    runGroups: groupRuns(entries, source),
246	    bundles,
247	    bundle,
248	    selectedRunId: bundle?.runId ?? requested ?? fallbackId,
249	    missingRunId,
250	    baseline: pickBaseline(bundle, bundles, params.get("baseline")),
251	    baselineCandidates: baselineCandidates(bundle, bundles),
252	    setRun,
253	    setBaseline,
254	    loading: !sourceReady || catalog.status === "loading",
255	    error: catalog.status === "error" ? catalog.error : undefined,
256	    reload,
257	    certificates,
258	    evidence,
259	  };
260	  return <DataContext.Provider value={value}>{children}</DataContext.Provider>;
261	}

