   1	// The web data layer — the only code that talks to `notary serve` or reads public/ data files.
   2	// Import from "src/data" (this file); see types.ts for the DataSource contract.
   3	import { PublishedFiles, type EvidenceEntry } from "./published";
   4	import type { FixtureIndex } from "../../../core/src/schema";
   5	import type { BundleIndexEntry } from "../../../core/src/schema";
   6	import type { RunEntry } from "./types";
