 109	/** Schema + content hash (+ agreement with its index entry). Throws, data withheld, otherwise. */
 110	export function validateBundle(raw: unknown, entry?: BundleIndexEntry): RunBundle {
 111	  const parsed = RunBundleSchema.safeParse(raw);
 112	  if (!parsed.success)
 113	    throw new Error("Bundle does not match the shared Notary schema. Data withheld.");
 114	  const bundle = parsed.data;
 115	  if (computeContentHash(bundle) !== bundle.contentHash)
 116	    throw new Error(`Content hash mismatch for ${bundle.runId}. Data withheld.`);
 117	  if (
 118	    entry &&
 119	    (entry.runId !== bundle.runId ||
 120	      entry.contentHash !== bundle.contentHash ||
 121	      entry.sample !== bundle.sample ||
 122	      entry.kind !== bundle.kind ||
 123	      entry.variant !== bundle.variant ||
 124	      entry.mode !== bundle.mode ||
 125	      entry.status !== bundle.status ||
 126	      entry.startedAt !== bundle.startedAt)
 127	  )
 128	    throw new Error("Bundle disagrees with its index entry. Data withheld.");
 129	  return bundle;
 130	}
