 135	  if (!parsed.success) throw new Error(`${what} does not match the shared Notary schema.`);
 136	  if (new Set(parsed.data.map((e) => e.runId)).size !== parsed.data.length)
 137	    throw new Error(`Duplicate run identifiers in ${what.toLowerCase()}.`);
 138	  return parsed.data;
