 144	/**
 145	 * Parse a timeline file and tie it to its verified bundle: same run, same sample flag, the
 146	 * bundle's content hash, events of this run with strictly increasing seq. Throws otherwise.
 147	 */
 148	export function verifyTimelineFile(raw: unknown, bundle: RunBundle): TimelineFile {
 149	  const parsed = TimelineFileSchema.safeParse(raw);
 150	  if (!parsed.success)
 151	    throw new Error(
 152	      `The timeline for ${bundle.runId} does not match the shared timeline schema. Data withheld.`,
 153	    );
 154	  const file = parsed.data;
 155	  if (file.runId !== bundle.runId)
 156	    throw new Error(`The timeline is for run ${file.runId}, not ${bundle.runId}. Data withheld.`);
 157	  if (file.sample !== bundle.sample)
 158	    throw new Error(
 159	      `The timeline's sample flag (${file.sample}) disagrees with the bundle (${bundle.sample}). Data withheld.`,
 160	    );
 161	  if (file.bundleHash !== bundle.contentHash)
 162	    throw new Error(
 163	      `Timeline hash mismatch for ${bundle.runId}: it belongs to bundle ${file.bundleHash.slice(0, 12)}…, not the verified bundle ${bundle.contentHash.slice(0, 12)}…. Data withheld.`,
 164	    );
 165	  file.events.forEach((e, i) => {
 166	    if (e.runId !== bundle.runId || (i > 0 && e.seq <= file.events[i - 1]!.seq))
 167	      throw new Error(`The timeline for ${bundle.runId} is out of order. Data withheld.`);
 168	  });
 169	  return file;
 170	}
