 174	/** sha256 of a certificate/revocation record without its own sha256 field. */
 175	export const sealOf = (record: { sha256: string }) => {
 176	  const { sha256: _ignored, ...rest } = record;
 177	  return sha256Hex(canonicalJson(rest));
 178	};
