 180	/** Every record's seal and sample flag. Throws (data withheld) on the first failure. */
 181	export function verifyToolRecords(tool: ToolCertificates, sample: boolean, file: string): ToolCertificates {
 182	  if (tool.sample !== sample)
 183	    throw new Error(`${file} mixes fixture and real certificate data. Data withheld.`);
 184	  for (const record of [...tool.certificates, ...tool.revocations]) {
 185	    if (sealOf(record) !== record.sha256)
 186	      throw new Error(`Seal mismatch for ${record.id}. Data withheld.`);
 187	    if (record.sample !== sample)
 188	      throw new Error(`${record.id} mixes fixture and real data. Data withheld.`);
 189	  }
 190	  return tool;
 191	}
