 193	/** Throws (data withheld) when a tool file, its report pin, or any record inside it fails. */
 194	export function verifyToolFile(
 195	  raw: unknown,
 196	  expectedHash: string | undefined,
 197	  sample: boolean,
 198	  file: string,
 199	): ToolCertificates {
 200	  const parsed = ToolCertificatesSchema.safeParse(raw);
 201	  if (!parsed.success)
 202	    throw new Error(`${file} does not match the shared certificate schema. Data withheld.`);
 203	  if (expectedHash === undefined || sha256Hex(canonicalJson(raw)) !== expectedHash)
 204	    throw new Error(`${file} does not match the hash pinned in its report. Data withheld.`);
 205	  return verifyToolRecords(parsed.data, sample, file);
