 211	/**
 212	 * Pick the fixture scenario for a run: the scenario that lists the run as a source bundle, else
 213	 * the scenario whose source bundles belong to the same simulated world (same scenarioKey, e.g.
 214	 * a queue run next to its notarize runs). Never another world: no match → undefined (the UI says
 215	 * no certificates were published for this run's world). Returns the reason shown on screen.
 216	 */
 217	export function chooseScenario(
 218	  index: FixtureIndex,
 219	  runId: string | undefined,
 220	): { scenario: FixtureIndex["scenarios"][number]; reason: string } | undefined {
 221	  if (!runId) return undefined;
 222	  const listed = index.scenarios.find((s) => s.sourceBundles.includes(runId));
 223	  if (listed)
 224	    return {
 225	      scenario: listed,
 226	      reason: `${runId} is a source bundle of fixture scenario "${listed.scenario}".`,
 227	    };
 228	  const key = scenarioKey(runId);
 229	  const sameWorld = index.scenarios.find((s) => s.sourceBundles.some((b) => scenarioKey(b) === key));
 230	  return sameWorld
 231	    ? {
 232	        scenario: sameWorld,
 233	        reason: `${runId} belongs to the same simulated world as fixture scenario "${sameWorld.scenario}" (its notarize runs are the certificate sources).`,
 234	      }
 235	    : undefined;
 236	}
