    47	/**
    48	 * Read and validate the published incidents. `missing` when nothing is published; throws (with a
    49	 * plain-language message) when the file is unreadable or does not match IncidentsIndexSchema.
    50	 * The bundle indexes are read alongside so each run can be checked against its published bundle.
    51	 */
    52	export async function loadIncidents(
    53	  opts: { signal?: AbortSignal; fetchImpl?: FetchImpl; base?: string } = {},
    54	): Promise<IncidentsLoad> {
    55	  const base = opts.base ?? baseUrl();
    56	  const fetchImpl = opts.fetchImpl ?? globalFetch;
    57	  const [rawReal, rawFixture] = await Promise.all([
    58	    readOptionalJson(`${base}incidents/index.json`, "incidents/index.json", opts.signal, fetchImpl),
    59	    readOptionalJson(`${base}incidents/fixture/index.json`, "incidents/fixture/index.json", opts.signal, fetchImpl),
    60	  ]);
    61	  if (rawReal === undefined && rawFixture === undefined) return { status: "missing" };
    62	  const parse = (raw: unknown, label: string): IncidentsIndex["runs"] => {
    63	    if (raw === undefined) return [];
    64	    const parsed = IncidentsIndexSchema.safeParse(raw);
    65	    if (!parsed.success) throw new Error(`${label} does not match the shared Notary schema. Incidents withheld.`);
    66	    // Each run keeps its own sample flag; a fixture index marks all of its runs as fixture.
    67	    return parsed.data.runs.map((r) => (parsed.data.sample ? { ...r, sample: true } : r));
    68	  };
    69	  const runs = [...parse(rawReal, "incidents/index.json"), ...parse(rawFixture, "incidents/fixture/index.json")];
    70	  const parsed = { data: { sample: false, runs } as IncidentsIndex };
    71	  const [primary, fixture] = await Promise.all([
    72	    readIndex(`${base}bundles/index.json`, "Bundle index", opts.signal, fetchImpl),
    73	    readIndex(`${base}bundles/fixture/index.json`, "Fixture index", opts.signal, fetchImpl),
    74	  ]);
    75	  return { status: "ready", index: parsed.data, primary, fixture };
    76	}
