  103	export type IncidentsView = {
  104	  cohort: Cohort;
  105	  /** Runs of the shown cohort, in file order (newest first). */
  106	  runs: RunView[];
  107	  /** Stats over the shown cohort's runs whose incidents are shown. */
  108	  stats: IncidentStats;
  109	  /** Runs published in the other cohort (fixture runs in the real view and vice versa). */
  110	  otherCohortRuns: number;
