  113	/** A run is fixture data when its file, or the whole index, says so (never shown as real). */
  114	export const isSampleRun = (file: IncidentsFile, indexSample: boolean) => file.sample || indexSample;
  115	
  116	function lookup(runId: string, reads: IndexRead[]): { entry?: BundleIndexEntry; unreadable?: string } {
  117	  for (const r of reads) {
  118	    const entry = r.entries?.find((e) => e.runId === runId);
  119	    if (entry) return { entry };
  120	  }
  121	  // Not found, and some index could not be read: the run may be listed there, so say "unchecked".
  122	  for (const r of reads) if (r.entries === null && r.error) return { unreadable: r.error };
  123	  return {};
  124	}
  125	
  126	/** Tie one run's incidents to its published index entry. */
  127	export function checkRun(file: IncidentsFile, sample: boolean, primary: IndexRead, fixture: IndexRead): RunCheck {
  128	  const { entry, unreadable } = lookup(file.runId, sample ? [fixture, primary] : [primary, fixture]);
  129	  if (!entry) return unreadable ? { state: "unchecked", reason: unreadable } : { state: "unpublished" };
  130	  if (entry.sample !== sample) return { state: "world_mismatch" };
  131	  if (entry.contentHash !== file.bundleHash)
  132	    return { state: "mismatch", indexHash: entry.contentHash, bundleHash: file.bundleHash };
  133	  return { state: "verified", entry };
  134	}
  135	
  136	export function runView(file: IncidentsFile, indexSample: boolean, primary: IndexRead, fixture: IndexRead): RunView {
  137	  const sample = isSampleRun(file, indexSample);
  138	  const check = checkRun(file, sample, primary, fixture);
  139	  const foreign = file.incidents.filter((i) => i.runId !== file.runId).length;
  140	  const shown = check.state !== "mismatch" && check.state !== "world_mismatch" && foreign === 0;
  141	  return {
  142	    runId: file.runId,
  143	    sample,
  144	    bundleHash: file.bundleHash,
  145	    sources: file.sources,
  146	    check,
  147	    foreign,
  148	    shown,
  149	    incidents: file.incidents,
  150	  };
  151	}
