  153	export function statsOf(incidents: readonly Incident[]): IncidentStats {
  154	  const bySeverity: Record<IncidentSeverity, number> = { warning: 0, error: 0 };
  155	  const byStatus: Record<IncidentResolutionStatus, number> = { resolved: 0, awaiting_human: 0, open: 0 };
  156	  const byKind: Partial<Record<IncidentKind, number>> = {};
  157	  for (const i of incidents) {
  158	    bySeverity[i.severity] += 1;
  159	    byStatus[i.resolution.status] += 1;
  160	    byKind[i.kind] = (byKind[i.kind] ?? 0) + 1;
  161	  }
  162	  return {
  163	    total: incidents.length,
  164	    resolved: byStatus.resolved,
  165	    awaitingHuman: byStatus.awaiting_human,
  166	    open: byStatus.open,
  167	    errors: bySeverity.error,
  168	    warnings: bySeverity.warning,
  169	    byKind,
  170	    bySeverity,
  171	    byStatus,
  172	  };
  173	}
