  180	  return {
  181	    cohort,
  182	    runs,
  183	    stats: statsOf(runs.filter((r) => r.shown).flatMap((r) => r.incidents)),
  184	    otherCohortRuns: all.length - runs.length,
  185	  };
  186	}
