    15	/** Trail for the current route: list page › record id (or just the page title). */
    16	export function useCrumbs(): { label: string; path?: string }[] {
    17	  const { pathname } = useLocation();
    18	  const match = matchAppRoute(pathname);
    19	  if (!match) return [{ label: "Not found" }];
    20	  const chain: AppRoute[] = [];
    21	  let r: AppRoute | undefined = match.route;
    22	  while (r) {
    23	    chain.unshift(r);
    24	    r = r.parent ? routeById(r.parent) : undefined;
    25	  }
    26	  const record = Object.values(match.params)[0];
    27	  return chain.map((c, i) => ({
    28	    label: i === chain.length - 1 && record ? decodeURIComponent(record) : c.title,
    29	    path: i === chain.length - 1 ? undefined : c.path,
    30	  }));
    31	}
