516	  if (top >= box.scrollTop + 8 && bottom <= box.scrollTop + box.clientHeight - 8) return;
517	  box.scrollTo({ top: Math.max(0, top - box.clientHeight / 2 + el.offsetHeight / 2), behavior: smooth ? "smooth" : "auto" });
