    // Only a certificate world that is provably this world (never another scenario's).
    if (cw.report && cw.world === key) {
      certificates = cw.tools.flatMap((t) => t.certificates);
      noCertificates = cw.tools.flatMap((t) => t.noCertificates);
    }
  } catch {
